"sections": [
{
"title": "Before you start",
"steps": [
{
"text": "Set a rack in the middle of the oven and heat it to <b>450°F</b>."
},
{
"text": "Rinse the sprouts and dry them thoroughly — dry sprouts brown, wet ones steam. Trim the dry stem ends without cutting so far that the leaves fall away."
},
{
"text": "Halve the sprouts through the stem. Quarter any unusually large ones so the pieces match in size."
}
]
},
{
"title": "Cook the beef bacon",
"option": "bacon",
"steps": [
{
"text": "Drain any liquid from the package and pat the bacon dry (do not rinse). Put the pieces in a cold skillet and set the burner to medium."
},
{
"text": "Cook, stirring often, until cooked through with crisp edges, following the package directions. Move to a paper-towel-lined plate.",
"timer": 8
},
{
"text": "Reserve 1 tablespoon of the rendered fat if you'd like to use it in place of some of the olive oil."
}
]
},
{
"title": "Roast the sprouts",
"steps": [
{
"text": "Toss the sprouts with the olive oil (or oil plus reserved bacon fat), salt, and pepper until thinly, evenly coated."
},
{
"text": "Arrange them <b>cut-side down</b> on the unlined sheet with space between pieces. Use two pans if they're crowded."
},
{
"text": "Roast 15 minutes, then check the undersides with a spatula. Small sprouts may be ready at 12 minutes.",
"timer": 15,
"tip": "Time-sensitive: you want deep golden-brown cut faces and centers a fork slides into with slight resistance."
},
{
"text": "If needed, roast 3–8 minutes more until deeply browned. Use oven mitts with the hot pan.",
"timer": 5
}
]
},
{
"title": "Glaze and finish",
"steps": [
{
"text": "While the sprouts roast, whisk the sweet chili sauce, balsamic vinegar, balsamic glaze, garlic powder, and pepper flakes (if using) in a small saucepan."
},
{
"text": "Warm over <b>medium-low</b>, stirring, until steaming and lightly coating a spoon. Don't let it boil hard — the sugars scorch fast.",
"timer": 3
},
{
"text": "Move the hot sprouts to a large heat-safe bowl. Toss with half the glaze, then add more a spoonful at a time until glossy but not puddled. You may not need it all."
},
{
"text": "Fold in the crisp beef bacon, transfer to a serving dish, shower with Parmesan, and serve right away.",
"optionText": {
"bacon": false,
"text": "Transfer to a serving dish, shower with Parmesan, and serve right away."
}
}
]
}
],
"notes": [
{
"title": "Kitchen Notes",
"items": [
{
"t": "li",
"text": "Small sprouts are what we remember from Good Charlie's — use them when you can."
},
{
"t": "li",
"text": "Tasting the first batch: was theirs sweeter, tangier, or hotter? Adjust the sweet chili, vinegar, or pepper flakes next time and note it here."
},
{
"t": "li",
"text": "For the bacon-free plate we actually ordered, turn off the beef bacon above and use the full 2 tablespoons of olive oil."
}
]
}
],
